CREATE TABLE `py_fund` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `fund_code` varchar(10) NOT NULL COMMENT '基金代码',
  `fund_name` varchar(100) NOT NULL COMMENT '基金名称 ',
  `exchange` varchar(50) NOT NULL COMMENT '交易所',
  `fund_category` varchar(50) NOT NULL COMMENT '资金类别',
  `opening_price` decimal(10,3) DEFAULT 0.000 COMMENT '开盘价',
  `highest_price` decimal(10,3) DEFAULT 0.000 COMMENT '最高价',
  `lowest_price` decimal(10,3) DEFAULT 0.000 COMMENT '最低价',
  `current_price` decimal(10,3) DEFAULT 0.000 COMMENT '当前价',
  `previous_close_price` decimal(10,3) DEFAULT 0.000 COMMENT '上一个收盘价',
  `price_change_percentage` decimal(8,3) DEFAULT 0.000 COMMENT '价格变化百分比',
  `volume` bigint(20) DEFAULT 0 COMMENT '成交量',
  `turnover` decimal(15,3) DEFAULT NULL,
  `update_time` datetime NOT NULL COMMENT '更新时间',
  `create_time` date NOT NULL COMMENT '创建时间',
  PRIMARY KEY (`id`),
  KEY `idx_fund_code` (`fund_code`),
  KEY `idx_exchange` (`exchange`),
  KEY `idx_category` (`fund_category`)
) ENGINE=InnoDB AUTO_INCREMENT=3091 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

